#!/usr/bin/env python3
"""قِمع التوظيف: من الأرقام تعرف أين تُصلح — لا من الإحساس."""
from dataclasses import dataclass

BENCHMARKS = {          # نسب تحويل مرجعية تقريبية لسوق .NET
    "applied_to_screen": 0.08,
    "screen_to_tech": 0.50,
    "tech_to_final": 0.30,
    "final_to_offer": 0.40,
}

@dataclass
class Funnel:
    applied: int
    screens: int
    techs: int
    finals: int
    offers: int

    def rates(self) -> dict[str, float]:
        safe = lambda a, b: (b / a) if a else 0.0
        return {
            "applied_to_screen": safe(self.applied, self.screens),
            "screen_to_tech": safe(self.screens, self.techs),
            "tech_to_final": safe(self.techs, self.finals),
            "final_to_offer": safe(self.finals, self.offers),
        }

    def diagnose(self) -> list[str]:
        tips = []
        r = self.rates()
        if r["applied_to_screen"] < BENCHMARKS["applied_to_screen"]:
            tips.append("مشكلة في السيرة/الملاءمة: أعد صياغة الإنجازات بأرقام وطابق كلمات الإعلان.")
        if self.screens and r["screen_to_tech"] < BENCHMARKS["screen_to_tech"]:
            tips.append("مشكلة في السكربت التعريفي/التوقعات: راجع 90 ثانية الأولى والراتب.")
        if self.techs and r["tech_to_final"] < BENCHMARKS["tech_to_final"]:
            tips.append("مشكلة تقنية: بنك الأسئلة + جولة live coding مسجّلة أسبوعيًا.")
        if self.finals and r["final_to_offer"] < BENCHMARKS["final_to_offer"]:
            tips.append("مشكلة سلوكية/تفاوض: قصص STAR ورقمك المستهدف جاهزان؟")
        return tips or ["كل النسب في المدى — استمر بنفس المعدل وزد العدد."]

def main() -> None:
    f = Funnel(applied=100, screens=9, techs=4, finals=1, offers=0)
    print(f"تقديم {f.applied} → رد {f.screens} → تقني {f.techs} → نهائي {f.finals} → عرض {f.offers}")
    for k, v in f.rates().items():
        print(f"  {k:<20} {v:6.1%}  (مرجع {BENCHMARKS[k]:.0%})")
    print("\nالتشخيص:")
    for t in f.diagnose():
        print(" ·", t)

if __name__ == "__main__":
    main()
